        const chunks = lunaAnalysisChunks(generation, doc.manifest, doc.draft, tags);
        if (doc.attemptsUsed + chunks.length > LIMITS.attempts) throw conflict('ADMIN_IMPORT_BUDGET_EXHAUSTED');
