    return typeof suggestion.slotId === 'string' && ['title', 'discNumber', 'trackNumber'].includes(suggestion.field) ? `tracks.${suggestion.slotId}.${suggestion.field as 'title' | 'discNumber' | 'trackNumber'}` : null;
